/// Returns true if the token represents a built-in function
pub fn is_builtin(t: TokenType) -> bool {
    let builtins = vec![
        TokenType::Abs,
        TokenType::Asc,
        TokenType::Atn,
        TokenType::ChrStr,
        TokenType::Cos,
        TokenType::Exp,
        TokenType::HexStr,
        TokenType::Instr,
        TokenType::Int,
        TokenType::LeftStr,
        TokenType::Len,
        TokenType::Ln,
        TokenType::Log,
        TokenType::MidStr,
        TokenType::RightStr,
        TokenType::Rnd,
        TokenType::Sgn,
        TokenType::Sin,
        TokenType::Spc,
        TokenType::Sqr,
        TokenType::StringStr,
        TokenType::StrStr,
        TokenType::Tan,
        TokenType::Val,
    ];
    builtins.contains(&t)
}

#[derive(Debug, Copy, Clone, PartialEq)]
pub enum IdentifierOrLiteralType {
    None,
    Integer,
    Float,
    String,
}

#[derive(Debug, Clone)]
pub struct Token {
    pub token_type: TokenType,
    pub value: String,
    pub identifier_or_literal_type: IdentifierOrLiteralType,
    pub is_array: bool, // Also set true for Functions - the VM just needs to check if the identifier is registered as a function
}

#[derive(Debug, Clone)]
pub struct Statement {
    pub tokens: Vec<Token>,
}